5037: function Get-MachineHealthPath {
5038:     $v = ([string]$env:CODEX_CONSULT_HEALTH).Trim()
5039:     if ($v) { if ($v -ieq 'none') { return '' }; return $v }
5040:     $h = Get-CodexHome
