5045: # { Path; Endpoints (object[]); Running (object[]) } - tolerant: absent or unreadable = empty.
5046: # Cached per process by the file's size and write time.
5047: function Read-MachineHealth {
5048:     param([switch]$Fresh)
5049:     $r = [pscustomobject]@{ Path = (Get-MachineHealthPath); Endpoints = [object[]]@(); Running = [object[]]@() }
5050:     if (-not $r.Path -or -not [IO.File]::Exists($r.Path)) { return $r }
5051:     $stamp = ''
5052:     try { $fi = New-Object IO.FileInfo($r.Path); $stamp = "$($fi.Length)|$($fi.LastWriteTimeUtc.Ticks)" } catch { return $r }
5053:     if (-not $Fresh -and $script:MachineHealthCache -and $script:MachineHealthCache.Path -eq $r.Path -and $script:MachineHealthCache.Stamp -eq $stamp) { return $script:MachineHealthCache.Data }
5054:     try {
5055:         $text = Read-SharedText -Path $r.Path
5056:         if ($text -and $text.Trim()) {
5057:             $data = ConvertFrom-JsonKeepOffset -Text $text
5058:             $r.Endpoints = [object[]]@(@(Get-PropertyValue $data 'endpoints' @()) | Where-Object { $null -ne $_ -and [string](Get-PropertyValue $_ 'endpoint' '') })
5059:             $r.Running = [object[]]@(@(Get-PropertyValue $data 'running' @()) | Where-Object { $null -ne $_ })
5060:         }
5061:     } catch { $r.Endpoints = [object[]]@(); $r.Running = [object[]]@() }
5062:     $script:MachineHealthCache = [pscustomobject]@{ Path = $r.Path; Stamp = $stamp; Data = $r }
5063:     return $r
5064: }
