5066: # The machine file's endpoint records of $Fingerprint as ledger-like entries for Get-EndpointHealth.
5067: function ConvertTo-MachineHealthEntries {
5068:     param([string]$Fingerprint)
5069:     $out = New-Object System.Collections.Generic.List[object]
5070:     if (-not $Fingerprint) { return , ([object[]]$out.ToArray()) }
5071:     foreach ($e in @((Read-MachineHealth).Endpoints)) {
5072:         if ([string](Get-PropertyValue $e 'endpoint' '') -ne $Fingerprint) { continue }
5073:         $when = Get-PropertyValue $e 'when' $null
5074:         if ($null -eq (ConvertTo-WhenOffset $when)) { continue }
5075:         $cls = [string](Get-PropertyValue $e 'class' '')
5076:         $repo = [string](Get-PropertyValue $e 'repo' '')
5077:         if ($cls -eq 'ok') {
5078:             $out.Add([pscustomobject]@{ n = 0; when = $when; finished_at = $when; bridge_outcome = 'usable reply'; reviewer = [pscustomobject]@{ provider_fingerprint = $Fingerprint }; provider_failure = $null })
5079:             continue
5080:         }
5081:         if (-not $cls) { continue }
5082:         # the provider's own reset time (retry_after), when it named one - the until of a failure
5083:         # without one is recomputed by Get-EndpointHealth (hit + 60 min, 10 for a burst)
5084:         $resetAt = Get-PropertyValue $e 'retry_after' $null
5085:         $pf = [pscustomobject]@{ class = $cls; kind = [string](Get-PropertyValue $e 'kind' ''); code = ''; message = [string](Get-PropertyValue $e 'message' ''); when = $when; retry_after = $(if ($null -ne (ConvertTo-WhenOffset $resetAt)) { $resetAt } else { $null }) }
5086:         $out.Add([pscustomobject]@{ n = 0; when = $when; finished_at = $when; bridge_outcome = "failed: $cls (machine-wide health; recorded by $repo)"; reviewer = [pscustomobject]@{ provider_fingerprint = $Fingerprint }; provider_failure = $pf })
5087:     }
5088:     return , ([object[]]$out.ToArray())
5089: }
