5091: # Changes the machine file under its lock - adds $AddEndpoint to endpoints[], drops every running
5092: # row of $RemovePid (> 0), adds $AddRunning to running[] - then prunes and writes it atomically.
5093: # $true when written; never throws.
5094: function Update-MachineHealth {
5095:     param($AddEndpoint = $null, $AddRunning = $null, [int]$RemovePid = 0)
5096:     $path = Get-MachineHealthPath
5097:     if (-not $path) { return $false }
5098:     $lockFs = $null
5099:     try {
5100:         $dir = [IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($path))
5101:         if (-not [IO.Directory]::Exists($dir)) { return $false }
5102:         $watch = [System.Diagnostics.Stopwatch]::StartNew()
5103:         $delay = 25
5104:         while ($null -eq $lockFs) {
5105:             try { $lockFs = [IO.File]::Open("$path.lock", [IO.FileMode]::OpenOrCreate, [IO.FileAccess]::ReadWrite, [IO.FileShare]::None) }
5106:             catch [System.IO.IOException] {
5107:                 if ($watch.Elapsed.TotalSeconds -ge 10) { return $false }
5108:                 Start-Sleep -Milliseconds $delay
5109:                 $delay = [Math]::Min($delay * 2, 500)
5110:             }
5111:         }
5112:         $cur = Read-MachineHealth -Fresh
5113:         $endpoints = New-Object System.Collections.Generic.List[object]
5114:         $running = New-Object System.Collections.Generic.List[object]
5115:         foreach ($e in @($cur.Endpoints)) { $endpoints.Add($e) }
5116:         foreach ($x in @($cur.Running)) { $running.Add($x) }
5117:         $data = [pscustomobject]@{ endpoints = $endpoints; running = $running }
5118:         if ($null -ne $AddEndpoint) { $endpoints.Add($AddEndpoint) }
5119:         if ($RemovePid -gt 0) { foreach ($x in @($running | Where-Object { [int](Get-PropertyValue $_ 'pid' 0) -eq $RemovePid })) { [void]$running.Remove($x) } }
5120:         if ($null -ne $AddRunning) { $running.Add($AddRunning) }
5121:         # prune: old records whose until has passed; running rows whose process is gone
5122:         $now = [DateTimeOffset]::UtcNow
5123:         $keepE = @($data.endpoints | Where-Object {
5124:                 $w = ConvertTo-WhenOffset (Get-PropertyValue $_ 'when' '')
5125:                 $u = ConvertTo-WhenOffset (Get-PropertyValue $_ 'until' '')
5126:                 ($null -ne $w) -and (($now - $w).TotalHours -le 24 -or ($null -ne $u -and $u -gt $now))
5127:             })
5128:         if ($keepE.Count -gt 500) { $keepE = @($keepE | Select-Object -Last 500) }
5129:         $keepR = @($data.running | Where-Object { Test-PidAlive -ProcessId ([int](Get-PropertyValue $_ 'pid' 0)) -StartTime (ConvertTo-StartIso (Get-PropertyValue $_ 'start_time' '')) })
5130:         $out = [pscustomobject]@{ health_version = 1; endpoints = [object[]]$keepE; running = [object[]]$keepR }
5131:         Write-TextAtomic -Path $path -Text ((ConvertTo-Json -InputObject $out -Depth 6) + "`n")
5132:         $script:MachineHealthCache = $null
5133:         return $true
5134:     } catch {
5135:         return $false
5136:     } finally {
5137:         if ($lockFs) { try { $lockFs.Dispose() } catch { } }
5138:     }
5139: }
