5141: # A run's outcome on an endpoint into the machine file: a usable reply (class ok) or its provider
5142: # failure ($Failure: the ledger's provider_failure; class operator is not the endpoint's). No-op
5143: # without a fingerprint or a file.
5144: function Add-MachineHealthRecord {
5145:     param([string]$Fingerprint, [string]$Outcome, $Failure = $null, [string]$Repo = '')
5146:     if (-not $Fingerprint -or -not (Get-MachineHealthPath)) { return $false }
5147:     $now = [DateTimeOffset]::Now
5148:     $rec = $null
5149:     if (Test-UsableOutcome $Outcome) {
5150:         $rec = [pscustomobject]@{ endpoint = $Fingerprint; class = 'ok'; kind = ''; until = $null; retry_after = $null; repo = $Repo; when = (Format-OffsetIso $now); message = '' }
5151:     } elseif ($null -ne $Failure) {
5152:         $cls = [string](Get-PropertyValue $Failure 'class' '')
5153:         if (-not $cls -or $cls -eq 'operator') { return $false }
5154:         $when = ConvertTo-WhenOffset (Get-PropertyValue $Failure 'when' '')
5155:         if ($null -eq $when) { $when = $now }
5156:         $kind = [string](Get-PropertyValue $Failure 'kind' '')
5157:         $until = $null
5158:         $ra = $null
5159:         if ($cls -eq 'quota') {
5160:             $ra = ConvertTo-WhenOffset (Get-PropertyValue $Failure 'retry_after' '')
5161:             if ($null -ne $ra) { $until = $ra } else { $until = $when.AddMinutes($(if ($kind -eq 'burst') { $script:BurstOutMinutes } else { $script:QuotaOutMinutes })) }
5162:         } elseif ($cls -eq 'auth') { $until = $when.AddHours(24) }
5163:         $msg = [string](Get-PropertyValue $Failure 'message' '')
5164:         if ($msg.Length -gt 200) { $msg = $msg.Substring(0, 200) }
5165:         $rec = [pscustomobject]@{ endpoint = $Fingerprint; class = $cls; kind = $kind; until = $(if ($null -ne $until) { Format-OffsetIso $until } else { $null }); retry_after = $(if ($null -ne $ra) { Format-OffsetIso $ra } else { $null }); repo = $Repo; when = (Format-OffsetIso $when); message = $msg }
5166:     }
5167:     if ($null -eq $rec) { return $false }
5168:     return (Update-MachineHealth -AddEndpoint $rec)
5169: }
