5836: function Select-RosterReviewer {
5837:     param($Roster, $Config, [object[]]$Consults, [string]$Launcher, [hashtable]$LoginCache = $null, [datetime]$UtcNow = [datetime]::UtcNow, [string]$OpenAiBaseUrl = '', [string]$Model = '', [switch]$SkipPreflight, [string]$Engine = '', [hashtable]$EngineLaunchers = $null, [switch]$NoNetwork, [hashtable]$Cache = $null, [int]$EstimateTokens = 0)
5838:     $skipped = New-Object System.Collections.Generic.List[object]
5839:     $r = [pscustomobject]@{ Entry = $null; Identity = $null; Verdict = $null; Skipped = [object[]]@(); Considered = 0; Error = '' }
5840:     $listing = New-Object System.Collections.Generic.List[string]
5841:     foreach ($e in @($Roster.Entries)) {
5842:         $entryEngine = if ($e.PSObject.Properties['Engine'] -and $e.Engine) { [string]$e.Engine } else { 'codex' }
5843:         if ($Engine -and $entryEngine -ne $Engine) { continue }
5844:         $entryLauncher = Get-EngineLauncher -Engine $entryEngine -Launchers $EngineLaunchers -CodexLauncher $Launcher
5845:         $id = Get-CachedReviewerIdentity -Cache $Cache -Config $Config -Provider $e.Provider -Model $e.Model -OpenAiBaseUrl $OpenAiBaseUrl -Engine $entryEngine -Launcher $entryLauncher
5846:         if ($Model -and $id.Model -cne $Model) { continue }
5847:         $r.Considered++
5848:         $block = Get-EngineLaunchBlock -Engine $entryEngine
5849:         if ($block) {
5850:             $skipped.Add([pscustomobject]@{ provider = $e.Provider; model = $id.Model; engine = $entryEngine; reason = "refused: $block" })
5851:             $listing.Add("#$($e.Position) $(Format-ReviewerLineage -Provider $id.Provider -Model $id.Model -Engine $entryEngine) (refused: $block)")
5852:             continue
5853:         }
5854:         # (wave 26b, D16) a brief its context window cannot hold
5855:         $ctxSkip = Get-ContextSkip -Entry $e -EstimateTokens $EstimateTokens
5856:         if ($ctxSkip) {
5857:             $skipped.Add([pscustomobject]@{ provider = $e.Provider; model = $id.Model; engine = $entryEngine; reason = $ctxSkip })
5858:             $listing.Add("#$($e.Position) $(Format-ReviewerLineage -Provider $id.Provider -Model $id.Model -Engine $entryEngine) ($ctxSkip)")
5859:             continue
5860:         }
5861:         if ($SkipPreflight) {
5862:             if ($id.Error) { $r.Error = $id.Error; return $r }
5863:             $r.Entry = $e; $r.Identity = $id
5864:             $r.Skipped = [object[]]$skipped.ToArray()
5865:             return $r
5866:         }
5867:         $health = $null
5868:         if ($id.Resolved) { $health = Get-CachedEndpointHealth -Cache $Cache -Consults $Consults -Fingerprint $id.Fingerprint -UtcNow $UtcNow }
5869:         $verdict = Get-PreflightVerdict -Identity $id -Config $Config -Launcher $entryLauncher -Health $health -LoginCache $LoginCache -Anonymous:($e.Auth -eq 'none') -RosterWalk -NoNetwork:$NoNetwork
5870:         if ($verdict.State -eq 'available') {
5871:             $r.Entry = $e; $r.Identity = $id; $r.Verdict = $verdict
5872:             $r.Skipped = [object[]]$skipped.ToArray()
5873:             return $r
5874:         }
5875:         $skipped.Add([pscustomobject]@{ provider = $e.Provider; model = $id.Model; engine = $entryEngine; reason = $verdict.Reason })
5876:         $listing.Add("#$($e.Position) $(Format-ReviewerLineage -Provider $id.Provider -Model $id.Model -Engine $entryEngine) ($($verdict.Reason))")
5877:     }
5878:     if ($r.Considered -eq 0) {
5879:         $all = (@($Roster.Entries) | ForEach-Object { "#$($_.Position) $(if ($_.Model) { Format-ReviewerLineage -Provider $_.Provider -Model $_.Model -Engine $_.Engine } else { "$($_.Provider) (config model)" })" }) -join ', '
5880:         if ($Engine -and -not $Model) {
5881:             $r.Error = "-Engine $($Engine): no entry of the reviewer roster '$($Roster.Path)' uses that engine ($all); pass -Provider <label> -Model <model> to choose a reviewer outside the roster"
5882:         } else {
5883:             $r.Error = "-Model $($Model): no entry of the reviewer roster '$($Roster.Path)' resolves to that model ($all); pass -Provider <name> -Model $Model to choose a reviewer outside the roster"
5884:         }
5885:         return $r
5886:     }
5887:     $r.Skipped = [object[]]$skipped.ToArray()
5888:     $r.Error = "no reviewer of the roster '$($Roster.Path)' is available; nothing was started: $($listing.ToArray() -join '; ') (run codex-providers.ps1 for the full picture)"
5889:     return $r
5890: }
