5892: # The purposes on which a "weighty" roster entry joins a panel.
5893: $script:WeightyPurposes = @('framing', 'decision', 'core-contract', 'acceptance', 'stuck')
5894: 
5895: # The members of a review panel (-Panel): the roster walked like Select-RosterReviewer
5896: # without stopping at the first available entry. Every entry whose preflight verdict is
5897: # available (with -SkipPreflight: every entry) runs, unless it is "weighty" and $Purpose is
5898: # light (not in $script:WeightyPurposes) and -All (-PanelAll) is not given, or its engine's
5899: # launch invariant refuses it (wave 23, D4 - with -SkipPreflight too). $Model: as for
5900: # the walk. -NoNetwork (wave 24, D15): passed to every preflight (an engine's sign-in that
5901: # needs the network is then "not checked") - the availability view of the hook and the listing
5902: # (Get-RosterAvailability) judges EVERY entry this way. { Members (object[], roster order, of {
5903: # Entry; Identity; State 'run'|'skipped'; Reason ('' when it runs); Verdict (the preflight
5904: # verdict, $null under -SkipPreflight or a launch refusal); Health (the endpoint health, $null
5905: # when unresolved); Block ('' or the launch refusal); SkipKind (wave 26: '' | refused |
5906: # unavailable | weighty - why it is skipped) }); Error ('' or the refusal: nobody runs / no entry
5907: # for $Model) }. (wave 26) Select-PanelRouting then seats the panel among the members that run
5908: # (State 'not-picked' for the rest).
5909: function Select-PanelMembers {

6383: # built); `<CollabDir>/roles/<name>.md` of the repository wins over the plugin's
6384: # `templates/role-<name>.md` (edge-cases, security, tests, docs ship). { Name; Path; Source
6385: # ('repository' | 'plugin'); Text; Error }.
6386: # (wave 26b, D1 / F22-1) A role file's containment: the text goes into the prompt of external
6387: # reviewers, so the file must be a regular file (no reparse point - symlink, junction - on the
6388: # file, nor on any directory from $Root down to it, $Root included) whose full path lies inside
6389: # $Root. '' when the file passes (or does not exist at all), else the reason. Attributes are read
6390: # without following links (FileSystemInfo.Attributes is the link's own).
6391: function Get-RoleFileProblem {
6392:     param([string]$Path, [string]$Root)
6393:     $sep = [IO.Path]::DirectorySeparatorChar
6394:     $cmp = $(if ($sep -eq '\') { [StringComparison]::OrdinalIgnoreCase } else { [StringComparison]::Ordinal })
6395:     $rootFull = [IO.Path]::GetFullPath($Root).TrimEnd('\', '/')
6396:     $full = [IO.Path]::GetFullPath($Path)
6397:     if (-not $full.StartsWith($rootFull + $sep, $cmp)) { return "'$Path' is outside '$rootFull'" }
6398:     $fi = New-Object IO.FileInfo($full)
6399:     $di = New-Object IO.DirectoryInfo($full)
6400:     if (-not $fi.Exists -and -not $di.Exists) {
6401:         # a dangling link reports neither; its attributes still read
6402:         $attr = $null
