6171: # the slot as 4 bytes big-endian) - bytes 0..7 pick (the weighted draw), bytes 8..15 decide
6172: # exploration (< 0.2). { Pick; Explore; Hex }.
6173: function Get-SlotUniforms {
6174:     param([byte[]]$Seed, [int]$Slot)
6175:     $buf = New-Object byte[] ($Seed.Length + 4)
6176:     [Array]::Copy($Seed, $buf, $Seed.Length)
6177:     $buf[$Seed.Length] = [byte](($Slot -shr 24) -band 255)
6178:     $buf[$Seed.Length + 1] = [byte](($Slot -shr 16) -band 255)
6179:     $buf[$Seed.Length + 2] = [byte](($Slot -shr 8) -band 255)
6180:     $buf[$Seed.Length + 3] = [byte]($Slot -band 255)
6181:     $sha = [System.Security.Cryptography.SHA256]::Create()
6182:     try { $h = $sha.ComputeHash($buf) } finally { $sha.Dispose() }
6183:     return [pscustomobject]@{ Pick = (ConvertTo-Uniform53 -Hash $h -Offset 0); Explore = (ConvertTo-Uniform53 -Hash $h -Offset 8); Hex = (ConvertTo-HexString $h) }
