6208:     $reserveTaken = 0
6209:     while ($seats.Count -lt $K -and $left.Count -gt 0) {
6210:         $slot = $seats.Count + 1
6211:         $seatedLabs = @($seats | ForEach-Object { [string]$_.Candidate.Lab } | Select-Object -Unique)
6212:         $pool = @()
6213:         $kind = 'rank'
6214:         if ($reserveTaken -lt $reserve) {
6215:             $pool = @($left | Where-Object { $seatedLabs -notcontains [string]$_.Lab -and [double]$_.Weight -ge $Neutral })
6216:             if ($pool.Count -gt 0) { $kind = 'lab' }
6217:         }
6218:         if ($pool.Count -eq 0) { $pool = @($left.ToArray()); $kind = 'rank' }
6219:         $u = Get-SlotUniforms -Seed $Seed -Slot $slot
6220:         $winner = $null
6221:         $rule = ''
6222:         if ($u.Explore -lt $Explore) {
6223:             $idx = [int][Math]::Floor($u.Pick * $pool.Count)
6224:             if ($idx -ge $pool.Count) { $idx = $pool.Count - 1 }
6225:             $winner = $pool[$idx]
6226:             $rule = "$kind-explore"
6227:         } else {
6228:             $total = 0.0
6229:             foreach ($c in $pool) { $total += [double]$c.Weight }
6230:             $target = $u.Pick * $total
6231:             $acc = 0.0
6232:             foreach ($c in $pool) {
6233:                 $acc += [double]$c.Weight
6234:                 if ($target -lt $acc) { $winner = $c; break }
6235:             }
